  HybridPaywallWebViewComponentDescriptor::HybridPaywallWebViewComponentDescriptor(const react::ComponentDescriptorParameters& parameters)
    : ConcreteComponentDescriptor(parameters,
                                  react::RawPropsParser(/* enableJsiParser */ true)) {}

  react::Props::Shared HybridPaywallWebViewComponentDescriptor::cloneProps(const react::PropsParserContext& context,
                                                                           const react::Props::Shared& props,
                                                                           react::RawProps rawProps) const {
    // 1. Prepare raw props parser
    rawProps.parse(rawPropsParser_);
    // 2. Copy props with Nitro's cached copy constructor
    return HybridPaywallWebViewShadowNode::Props(context, /* & */ rawProps, props);
  }

#ifdef ANDROID
  void HybridPaywallWebViewComponentDescriptor::adopt(react::ShadowNode& shadowNode) const {
    // This is called immediately after `ShadowNode` is created, cloned or in progress.
    // On Android, we need to wrap props in our state, which gets routed through Java and later unwrapped in JNI/C++.
    auto& concreteShadowNode = dynamic_cast<HybridPaywallWebViewShadowNode&>(shadowNode);
    const HybridPaywallWebViewProps& props = concreteShadowNode.getConcreteProps();
    HybridPaywallWebViewState state;
    state.setProps(props);
    concreteShadowNode.setStateData(std::move(state));
  }
#endif

